let grid = [];
let cols, rows;
let cellSize = 20;
let maxAge = 80;

let seed;
let colors = [];
let colorbg;
let loopFrames = 600;

function setup() {
	seed = int(random(999999));
	randomSeed(seed);

	createCanvas(windowWidth, windowHeight);
	colorbg = random(bgcolor);
	colors = random(colorScheme).colors;
	background(colorbg);

	cols = floor(width / cellSize);
	rows = floor(height / cellSize);

	// 初始全空
	for (let i = 0; i < cols; i++) {
		grid[i] = [];
		for (let j = 0; j < rows; j++) {
			grid[i][j] = {
				alive: false,
				age: 0,
				shape: random(["circle", "triangle", "rect", "leiwen"])
			};
		}
	}
}

function draw() {
	background(color(colorbg + "33")); // 半透明背景制造尾迹

	// 每隔一段时间新增几个活细胞作为“生长起点”
	if (frameCount % 50 === 0) {
		for (let k = 0; k < 3; k++) {
			let x = floor(random(cols));
			let y = floor(random(rows));
			grid[x][y].alive = true;
			grid[x][y].age = 0;
			grid[x][y].shape = random(["circle", "triangle", "rect", "leiwen"]);
		}
	}

	// 绘制活细胞
	for (let i = 0; i < cols; i++) {
		for (let j = 0; j < rows; j++) {
			let cell = grid[i][j];
			if (cell.alive) {
				let size = map(cell.age, 0, maxAge, 2, cellSize);
				fill(getFlowingColor(i, j, cell.age));
				noStroke();
				push();
				translate(i * cellSize + cellSize / 2, j * cellSize + cellSize / 2);
				drawShape(cell.shape, size);
				pop();

			}
		}
	}

	updateGrowth();

	// 让整体有呼吸般的自然循环感觉（用颜色alpha或大小调节）
}

// 绘制形状
function drawShape(shape, s) {
	switch (shape) {
		case "circle":
			ellipse(0, 0, s);
			// drawLeiWen(s);
			break;
		case "triangle":
			let h = s * sqrt(3) / 2;
			triangle(0, -h / 2, -s / 2, h / 2, s / 2, h / 2);
			break;
		case "rect":
			rectMode(CENTER);
			// rect(0, 0, s, s);
			drawLeiWen(s);
			break;
		case "leiwen":
			drawLeiWen(s);
			break;
	}
}

// 渐变循环色彩，带呼吸节奏
function getFlowingColor(i, j, age) {
	let px = i / cols;
	let py = j / rows;
	let loopProg = (frameCount % loopFrames) / loopFrames;
	let theta = loopProg * TWO_PI;

	let wave = sin(px * 2 + py * 2 + theta) * 0.5 + 0.5;
	let ageFactor = constrain(age / maxAge, 0, 1);
	let breathing = sin(loopProg * TWO_PI) * 0.5 + 0.5;

	let blend = (wave * 0.5 + ageFactor * 0.3 + breathing * 0.2);

	let indexA = floor(blend * (colors.length - 1));
	let indexB = (indexA + 1) % colors.length;
	let mix = (blend * (colors.length - 1)) % 1;

	let c = lerpColor(color(colors[indexA]), color(colors[indexB]), mix);
	c.setAlpha(150 + 80 * breathing);
	return c;
}

// 细胞扩散生长逻辑
function updateGrowth() {
	let next = [];
	for (let i = 0; i < cols; i++) {
		next[i] = [];
		for (let j = 0; j < rows; j++) {
			// 先默认复制上一代状态
			next[i][j] = {
				...grid[i][j]
			};
		}
	}

	for (let i = 0; i < cols; i++) {
		for (let j = 0; j < rows; j++) {
			let cell = grid[i][j];
			if (cell.alive) {
				next[i][j].age++;

				if (next[i][j].age > maxAge) {
					next[i][j].alive = false;
				} else {
					// 找活细胞邻居，随机激活一个邻居
					let neighbors = getNeighbors(i, j).filter(n => !grid[n.x][n.y].alive);
					for (let n of neighbors) {
						// 5%几率激活邻居
						if (random() < 0.05) {
							next[n.x][n.y] = {
								alive: true,
								age: 0,
								shape: random(["circle", "triangle", "rect", "leiwen"])
							};
						}
					}
				}
			}
		}
	}
	grid = next;
}



// 获取邻居坐标（上下左右，考虑边界）
function getNeighbors(x, y) {
	let neighbors = [];
	if (x > 0) neighbors.push({
		x: x - 1,
		y: y
	});
	if (x < cols - 1) neighbors.push({
		x: x + 1,
		y: y
	});
	if (y > 0) neighbors.push({
		x: x,
		y: y - 1
	});
	if (y < rows - 1) neighbors.push({
		x: x,
		y: y + 1
	});
	return neighbors;
}

function drawLeiWen(s) {
	// randomSeed(seed);
	noFill();
	stroke(random(colors));
	strokeWeight(1.5);
	// rotate(random([PI/2, PI, PI/2*3, PI*2]))
	beginShape();
	let step = s / 5;
	let x = -s / 2,
		y = -s / 2;
	for (let i = 0; i < 5; i++) {
		vertex(x + i * step, y);
		vertex(x + i * step, y + (i + 1) * step);
		vertex(x + (i + 1) * step, y + (i + 1) * step);
	}
	endShape();
}

